gKu(){return"\u041f\u043e\u0432\u0456\u0434\u043e\u043c\u0438\u0442\u0438 \u043f\u0440\u043e \u043f\u043e\u043c\u0438\u043b\u043a\u0443"},
gKt(){return"\u0422\u0435\u0445\u043d\u0456\u0447\u043d\u0456 \u043b\u043e\u0433\u0438 \u0441\u043a\u043e\u043f\u0456\u0439\u043e\u0432\u0430\u043d\u043e \u0434\u043e \u0431\u0443\u0444\u0435\u0440\u0430 \u043e\u0431\u043c\u0456\u043d\u0443. \u0411\u0443\u0434\u044c \u043b\u0430\u0441\u043a\u0430, \u043d\u0430\u0434\u0456\u0448\u043b\u0456\u0442\u044c \u0457\u0445 \u043d\u0430:"},
gKv(){return"\u0411\u0443\u0434\u044c \u043b\u0430\u0441\u043a\u0430, \u043a\u043e\u0440\u043e\u0442\u043a\u043e \u043e\u043f\u0438\u0448\u0456\u0442\u044c \u043f\u043e\u043c\u0438\u043b\u043a\u0443 \u0442\u0430 \u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u0432 \u043b\u0438\u0441\u0442\u0456 \u0442\u0435\u0445\u043d\u0456\u0447\u043d\u0443 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044e, \u044f\u043a\u0443 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e \u0441\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0432 \u0434\u043e \u0431\u0443\u0444\u0435\u0440\u0430 \u043e\u0431\u043c\u0456\u043d\u0443. \u042f\u043a\u0449\u043e \u043c\u043e\u0436\u043b\u0438\u0432\u043e, \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u0437\u043d\u0456\u043c\u043e\u043a \u0435\u043a\u0440\u0430\u043d\u0430. \u0414\u044f\u043a\u0443\u0454\u043c\u043e, \u0449\u043e \u0434\u043e\u043f\u043e\u043c\u0430\u0433\u0430\u0454\u0442\u0435 \u0437\u0440\u043e\u0431\u0438\u0442\u0438 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u043a\u0440\u0430\u0449\u0438\u043c."},
